here (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid))  AND score >= :score  and dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''5 minutes'') at time zone :timeZone ) AND CURRENT_TIMESTAMP at time zone :timeZone and itenantid = :tenantid order by ilivemessageid desc limit 50;",
        "Other": "select (select elem -> ''transaction'' ->> ''referenceNumber'' from jsonb_array_elements(risk_context -> ''attribs'') elem limit 1) AS \\"Post-Auth RRN\\", (select elem ->> ''failureCode'' from jsonb_array_elements(risk_context -> ''attribs'') elem limit 1) AS \\"Failure Code\\", (select elem ->> ''failureMessage'' from jsonb_array_elements(risk_context -> ''attribs'') elem limit 1) AS \\"Failure Message\\",  observations -> ''transaction'' -> ''method''->>''typeNarration'' AS \\"Type Description\\", observations -> ''transaction'' -> ''method''->>''subTypeNarration'' AS \\"Sub-Type Description\\", observations -> ''txn'' -> ''attribs'' ->> ''referenceNumber'' AS \\"RRN\\", result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime  as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast ( observations->''txn''->''type''->>-1 as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans where score >= :score  and dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''5 minutes'') at time zone :timeZone ) AND CURRENT_TIMESTAMP at time zone :timeZone and vcclassname  = :className and itenantid = :tenantid order by ilivemessageid desc limit 50;"
    },
