ere (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) AND score >= :score and dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''5 minutes'') at time zone :timeZone ) AND CURRENT_TIMESTAMP at time zone :timeZone and ilivemessageid > :iLiveMessageID and itenantid = :tenantid order by ilivemessageid desc limit 1000;",
